import numpy as np
from scipy.optimize import minimize
import time

def compute_c5(h, n):
    dx = 2.0 / n
    return float(np.max(np.correlate(h, 1 - h, mode='full')) * dx)

def compute_c5_vec(h, n):
    dx = 2.0 / n
    return np.correlate(h, 1 - h, mode='full') * dx

def project_feasible(h, n):
    target = n / 2.0
    h = np.clip(h.copy(), 0.0, 1.0)
    for _ in range(2000):
        diff = target - h.sum()
        if abs(diff) < 1e-15:
            break
        if diff > 0:
            room = 1.0 - h
            tot = room.sum()
            if tot < 1e-15:
                break
            h += (diff / tot) * room
        else:
            tot = h.sum()
            if tot < 1e-15:
                break
            h += (diff / tot) * h
    return np.clip(h, 0.0, 1.0)

def grad_smooth_max(h, n, alpha):
    c = compute_c5_vec(h, n)
    c_shift = alpha * (c - c.max())
    mx = c_shift.max()
    w = np.exp(c_shift - mx)
    w /= w.sum()
    dx = 2.0 / n
    grad = np.zeros(n)
    for m in range(2 * n - 1):
        if w[m] < 1e-14:
            continue
        k = m - (n - 1)
        wm = w[m] * dx
        if k >= 0:
            nv = n - k
            grad[:nv] += wm * (1.0 - h[k:])
            grad[k:] += wm * (-h[:nv])
        else:
            kk = -k
            nv = n - kk
            grad[kk:] += wm * (1.0 - h[:nv])
            grad[:nv] += wm * (-h[kk:])
    return grad

def _obj(x, n, alpha, mu):
    c = compute_c5_vec(x, n)
    m = c.max()
    sh = alpha * (c - m)
    mx = sh.max()
    val = m + (mx + np.log(np.sum(np.exp(sh - mx)))) / alpha
    val += mu * (x.sum() - n / 2.0) ** 2
    return float(val)

def _grad(x, n, alpha, mu):
    g = grad_smooth_max(x, n, alpha)
    s = x.sum() - n / 2.0
    g += 2.0 * mu * s
    return g

def _eq(x, n):
    return float(x.sum() - n / 2.0)

def _eq_jac(x, n):
    return np.ones(n)

def _slsqp_obj(x, n, alpha):
    c = compute_c5_vec(x, n)
    m = c.max()
    sh = alpha * (c - m)
    mx = sh.max()
    return float(m + (mx + np.log(np.sum(np.exp(sh - mx)))) / alpha)

def lbfgs_optimize(h, n, deadline, max_iters=500):
    best_c = compute_c5(h, n)
    bounds = [(0.0, 1.0)] * n
    configs = [(100, 0.5), (500, 2.0), (2000, 10.0),
               (10000, 50.0), (50000, 200.0),
               (200000, 1000.0), (1000000, 5000.0),
               (5000000, 20000.0), (20000000, 100000.0)]
    for alpha, mu in configs:
        if time.time() > deadline - 3:
            break
        try:
            res = minimize(_obj, h, jac=_grad,
                         args=(n, alpha, mu), method='L-BFGS-B',
                         bounds=bounds,
                         options={'maxiter': max_iters, 'ftol': 1e-18,
                                  'gtol': 1e-16, 'maxfun': max_iters * 50,
                                  'maxls': 100})
            h_new = project_feasible(res.x, n)
            c_new = compute_c5(h_new, n)
            if c_new < best_c:
                best_c = c_new
                h = h_new
        except Exception:
            pass
    return h, best_c

def slsqp_optimize(h, n, deadline, alpha=2000000, maxiter=5000):
    bounds = [(0.0, 1.0)] * n
    cons = [{'type': 'eq', 'fun': _eq, 'jac': _eq_jac, 'args': (n,)}]
    try:
        res = minimize(_slsqp_obj, h, args=(n, alpha), method='SLSQP',
                      bounds=bounds, constraints=cons,
                      options={'maxiter': maxiter, 'ftol': 1e-18})
        h_new = project_feasible(res.x, n)
        c_new = compute_c5(h_new, n)
        return h_new, c_new
    except Exception:
        return h.copy(), compute_c5(h, n)

def grad_steepest(h, n, deadline, k_top=60):
    best_c = compute_c5(h, n)
    alphas = [500, 5000, 50000, 500000]
    for alpha in alphas:
        while time.time() < deadline:
            g = grad_smooth_max(h, n, alpha)
            up = np.argsort(g)[-k_top:]
            down = np.argsort(g)[:k_top]
            improved = False
            for i in down:
                if time.time() > deadline:
                    return h, best_c
                for j in up:
                    if i == j:
                        continue
                    for step in [0.005, 0.002, 0.001, 0.0005, 0.0002]:
                        if h[i] + step <= 1.0 and h[j] - step >= 0.0:
                            h[i] += step
                            h[j] -= step
                            c = compute_c5(h, n)
                            if c < best_c - 1e-15:
                                best_c = c
                                improved = True
                            else:
                                h[i] -= step
                                h[j] += step
                            if improved:
                                break
            if not improved:
                break
    return h, best_c

def local_pair_search(h, n, deadline, radius=100):
    best_c = compute_c5(h, n)
    steps = [0.01, 0.005, 0.002, 0.001, 0.0005, 0.0002, 0.0001, 5e-5, 2e-5, 1e-5]
    for d in steps:
        while time.time() < deadline:
            any_imp = False
            for i in range(n):
                if time.time() > deadline:
                    return h, best_c
                lo = max(0, i - radius)
                hi = min(n, i + radius + 1)
                for j in range(lo, hi):
                    if i == j:
                        continue
                    if h[i] + d <= 1.0 and h[j] - d >= 0.0:
                        h[i] += d
                        h[j] -= d
                        c = compute_c5(h, n)
                        if c < best_c - 1e-15:
                            best_c = c
                            any_imp = True
                        else:
                            h[i] -= d
                            h[j] += d
                    if h[j] + d <= 1.0 and h[i] - d >= 0.0:
                        h[j] += d
                        h[i] -= d
                        c = compute_c5(h, n)
                        if c < best_c - 1e-15:
                            best_c = c
                            any_imp = True
                        else:
                            h[j] -= d
                            h[i] += d
            if not any_imp:
                break
    return h, best_c

def global_pair_fine(h, n, deadline):
    best_c = compute_c5(h, n)
    steps = [0.001, 0.0005, 0.0002, 0.0001, 5e-5, 2e-5, 1e-5, 5e-6]
    for d in steps:
        while time.time() < deadline:
            any_imp = False
            for i in range(n):
                if time.time() > deadline:
                    return h, best_c
                for j in range(i + 1, n):
                    if h[i] + d <= 1.0 and h[j] - d >= 0.0:
                        h[i] += d
                        h[j] -= d
                        c = compute_c5(h, n)
                        if c < best_c - 1e-15:
                            best_c = c
                            any_imp = True
                        else:
                            h[i] -= d
                            h[j] += d
                    if h[j] + d <= 1.0 and h[i] - d >= 0.0:
                        h[j] += d
                        h[i] -= d
                        c = compute_c5(h, n)
                        if c < best_c - 1e-15:
                            best_c = c
                            any_imp = True
                        else:
                            h[j] -= d
                            h[i] += d
            if not any_imp:
                break
    return h, best_c

def fourier_flat_start(n, rng):
    h = np.full(n, 0.5)
    fft_h = np.fft.rfft(h)
    for k in range(1, len(fft_h)):
        phase = rng.uniform(0, 2.0 * np.pi)
        fft_h[k] = np.abs(fft_h[k]) * np.exp(1j * phase)
    h = np.fft.irfft(fft_h, n=n)
    return project_feasible(h, n)

def golden_start(n):
    h = np.zeros(n)
    half = n // 2
    phi = (1.0 + np.sqrt(5.0)) / 2.0
    positions = np.floor(np.arange(half) * phi).astype(int) % n
    h[positions] = 1.0
    return project_feasible(h, n)

def perturbed_start(h, n, rng, scale=0.03):
    h_p = h + rng.randn(n) * scale
    return project_feasible(h_p, n)

def run(seed=42, budget_s=1100, **kwargs):
    t0 = time.time()
    rng = np.random.RandomState(seed)
    deadline = t0 + budget_s - 3

    try:
        h_init = np.array(initial_h_values, dtype=float).copy()
        n_init = len(h_init)
    except Exception:
        h_init = np.full(500, 0.5)
        n_init = 500

    best_h = project_feasible(h_init, n_init)
    best_c = compute_c5(best_h, n_init)
    best_n = n_init

    # Phase 1: L-BFGS-B on parent
    t1 = min(t0 + 180, deadline - 500)
    best_h, best_c = lbfgs_optimize(best_h, best_n, t1, max_iters=600)

    # Phase 2: SLSQP polish
    if time.time() < deadline - 400:
        t2 = min(time.time() + 55, deadline - 400)
        h, c = slsqp_optimize(best_h, best_n, t2, alpha=5000000, maxiter=6000)
        if c < best_c:
            best_c, best_h = c, h

    # Phase 3: Gradient-directed steepest
    if time.time() < deadline - 300:
        t3 = min(time.time() + 50, deadline - 300)
        h, c = grad_steepest(best_h, best_n, t3, k_top=50)
        if c < best_c:
            best_c, best_h = c, h

    # Phase 4: Try n=650
    if time.time() < deadline - 250:
        n_new = 650
        x_old = np.linspace(0, 2, best_n, endpoint=False)
        x_new = np.linspace(0, 2, n_new, endpoint=False)
        h_interp = np.interp(x_new, x_old, best_h)
        h_interp = project_feasible(h_interp, n_new)
        alloc = min(130, (deadline - time.time() - 150) * 0.55)
        if alloc > 30:
            h_t, c_t = lbfgs_optimize(h_interp, n_new, time.time() + alloc, max_iters=400)
            if time.time() < deadline - 100:
                t4 = min(time.time() + 35, deadline - 100)
                h_t, c_t = slsqp_optimize(h_t, n_new, t4, alpha=5000000, maxiter=4000)
            if c_t < best_c:
                best_c, best_h, best_n = c_t, h_t, n_new

    # Phase 5: Try n=400 (coarser, may find better shape)
    if time.time() < deadline - 200:
        n_coarse = 400
        x_old = np.linspace(0, 2, best_n, endpoint=False)
        x_coarse = np.linspace(0, 2, n_coarse, endpoint=False)
        h_coarse = np.interp(x_coarse, x_old, best_h)
        h_coarse = project_feasible(h_coarse, n_coarse)
        alloc = min(80, (deadline - time.time() - 100) * 0.4)
        if alloc > 20:
            h_t, c_t = lbfgs_optimize(h_coarse, n_coarse, time.time() + alloc, max_iters=400)
            if c_t < best_c:
                best_c, best_h, best_n = c_t, h_t, n_coarse

    # Phase 6: Diverse restarts at best_n
    starts = [fourier_flat_start(best_n, rng),
              golden_start(best_n),
              perturbed_start(best_h, best_n, rng, 0.02),
              perturbed_start(best_h, best_n, rng, 0.05)]
    for s in starts:
        if time.time() > deadline - 70:
            break
        alloc = min(20, (deadline - time.time() - 40) * 0.45)
        if alloc < 8:
            break
        h_s, c_s = lbfgs_optimize(s, best_n, time.time() + alloc, max_iters=300)
        if c_s < best_c:
            best_c, best_h = c_s, h_s

    # Phase 7: Intensive local pair search
    if time.time() < deadline - 15:
        best_h, best_c = local_pair_search(best_h, best_n, deadline - 10, radius=100)

    # Phase 8: Global fine pair search
    if time.time() < deadline - 3:
        best_h, best_c = global_pair_fine(best_h, best_n, deadline - 1)

    # Phase 9: Final SLSQP squeeze
    if time.time() < deadline - 2:
        h_f, c_f = slsqp_optimize(best_h, best_n, deadline - 1, alpha=10000000, maxiter=2000)
        if c_f < best_c:
            best_c, best_h = c_f, h_f

    best_h = project_feasible(best_h, best_n)
    best_c = compute_c5(best_h, best_n)
    return best_h, best_c, best_n
